"""A small YAML reader for document metadata and CLI defaults."""
import re,json

def split_flow(s):
    out=[];q=None;level=0;start=0
    for i,c in enumerate(s):
        if q:
            if c==q and (i==0 or s[i-1]!='\\'):q=None
        elif c in '\"\'':q=c
        elif c in '[{(':level+=1
        elif c in ']})':level-=1
        elif c==',' and level==0:out.append(s[start:i].strip());start=i+1
    out.append(s[start:].strip());return out

def scalar(s):
    s=s.strip()
    if s.startswith('[') and s.endswith(']'):return [scalar(x) for x in split_flow(s[1:-1]) if x]
    if s.startswith('{') and s.endswith('}'):
        out={}
        for x in split_flow(s[1:-1]):
            if ':' in x:
                k,v=x.split(':',1);out[str(scalar(k))]=scalar(v)
        return out
    if len(s)>=2 and s[0]==s[-1]=='"':
        try:return json.loads(s)
        except:return s[1:-1]
    if len(s)>=2 and s[0]==s[-1]=="'":return s[1:-1].replace("''", "'")
    s=re.sub(r'\s+#.*$','',s)
    if s.lower() in ['null','~','']:return None
    if s.lower() in ['true','yes','on']:return True
    if s.lower() in ['false','no','off']:return False
    return s

def loads(text):
    try:return json.loads(text)
    except:pass
    ls=text.expandtabs(4).splitlines(); n=len(ls)
    def parse(i,ind):
