                        if lev<=ind:break
                        if sub is None:sub=lev
                    collected.append(ls[j][sub or ind+2:]);j+=1
                v='\n'.join(collected)
                if val.startswith('>'):v=re.sub(r'(?<=\S)\n(?=\S)',' ',v)
                if not val.endswith('-'):v+='\n'
                i=j
            elif not val:
                j=i
                while j<n and not ls[j].strip():j+=1
                if j<n and (len(ls[j])-len(ls[j].lstrip())>ind or (not islist and ls[j].lstrip().startswith('- ') and len(ls[j])-len(ls[j].lstrip())==ind)):
                    v,i=parse(j,len(ls[j])-len(ls[j].lstrip()))
                else:v=None
