import yamlish

class MarkdownReader:
    def __init__(self,extensions,options=None):
        self.ext=set(extensions); self.options=options or {};self.refs={};self.notes={};self.ids=set();self.meta={};self.example=0
        self.common=self.options.get('reader','') in ['gfm','commonmark','commonmark_x']
    def has(self,e):return e in self.ext
    def unique(self,x):
        y=x;n=1
        while y in self.ids:y=x+'-'+str(n);n+=1
        self.ids.add(y);return y
    def read(self,text):
        text=text.replace('\r\n','\n').replace('\r','\n').lstrip('\ufeff')
        if not self.options.get('preserve-tabs'):text=text.expandtabs(int(self.options.get('tab-stop',4)))
        ls=text.split('\n')
        if self.has('pandoc_title_block') and ls and ls[0].startswith('%'):
            vals=[]
            while ls and ls[0].startswith('%') and len(vals)<3:
                val=ls.pop(0)[1:].strip()
                while ls and re.match(r'^\s+\S',ls[0]):val+='\n'+ls.pop(0).strip()
                vals.append(val)
            for k,v in zip(['title','author','date'],vals):
                if k=='author':self.meta[k]=N('MetaList',[N('MetaInlines',self.inline(x.strip())) for x in re.split(r';|\n',v) if x.strip()])
                elif v:self.meta[k]=N('MetaInlines',self.inline(v))
        # YAML blocks are collected before inline parsing so metadata can contain notes.
